package com.accessaudit.service;
import com.accessaudit.model.*; import com.accessaudit.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service public class CatalogService {
 private final DirectoryUserRepository users; private final ManagedSystemRepository systems; private final AccessProfileRepository profiles; private final AuditEventRepository audit;
 public CatalogService(DirectoryUserRepository u,ManagedSystemRepository s,AccessProfileRepository p,AuditEventRepository a){users=u;systems=s;profiles=p;audit=a;}
 public List<DirectoryUser> users(){return users.findAllByOrderByFullNameAsc();} public List<ManagedSystem> systems(){return systems.findAllByOrderByNameAsc();} public List<AccessProfile> profiles(){return profiles.findAllByOrderBySystemNameAscNameAsc();}
 @Transactional public DirectoryUser saveUser(Long id,Map<String,Object>b){String name=req(b,"fullName"),email=req(b,"email").toLowerCase(Locale.ROOT),dept=req(b,"department"),title=req(b,"jobTitle");if(!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new IllegalArgumentException("Informe um e-mail válido.");if(id==null&&users.existsByEmailIgnoreCase(email)||id!=null&&users.existsByEmailIgnoreCaseAndIdNot(email,id))throw new IllegalArgumentException("Já existe um usuário com esse e-mail.");DirectoryUser u=id==null?new DirectoryUser(name,email,dept,title,bool(b,"active",true)):users.findById(id).orElseThrow(()->new NoSuchElementException("Usuário não encontrado."));u.setFullName(name);u.setEmail(email);u.setDepartment(dept);u.setJobTitle(title);u.setActive(bool(b,"active",true));u=users.save(u);audit.save(new AuditEvent("USER",u.getId(),id==null?"USER_CREATED":"USER_UPDATED",actor(b),name+" ("+email+")"));return u;}
 @Transactional public void deleteUser(Long id,Map<String,Object>b){DirectoryUser u=users.findById(id).orElseThrow(()->new NoSuchElementException("Usuário não encontrado."));u.setActive(false);users.save(u);audit.save(new AuditEvent("USER",id,"USER_DEACTIVATED",actor(b),u.getFullName()+" desativado."));}
 @Transactional public ManagedSystem saveSystem(Long id,Map<String,Object>b){String name=req(b,"name"),code=req(b,"code").toUpperCase(Locale.ROOT),desc=req(b,"description"),owner=req(b,"ownerTeam"),crit=req(b,"criticality").toUpperCase(Locale.ROOT);if(!Set.of("BAIXO","MÉDIO","ALTO","CRÍTICO").contains(crit))throw new IllegalArgumentException("Criticidade inválida.");if(id==null&&systems.existsByCodeIgnoreCase(code)||id!=null&&systems.existsByCodeIgnoreCaseAndIdNot(code,id))throw new IllegalArgumentException("Já existe um sistema com esse código.");ManagedSystem s=id==null?new ManagedSystem(name,code,desc,owner,crit,bool(b,"active",true)):systems.findById(id).orElseThrow(()->new NoSuchElementException("Sistema não encontrado."));s.setName(name);s.setCode(code);s.setDescription(desc);s.setOwnerTeam(owner);s.setCriticality(crit);s.setActive(bool(b,"active",true));s=systems.save(s);audit.save(new AuditEvent("SYSTEM",s.getId(),id==null?"SYSTEM_CREATED":"SYSTEM_UPDATED",actor(b),name+" ("+code+")"));return s;}
 @Transactional public void deleteSystem(Long id,Map<String,Object>b){ManagedSystem s=systems.findById(id).orElseThrow(()->new NoSuchElementException("Sistema não encontrado."));s.setActive(false);systems.save(s);audit.save(new AuditEvent("SYSTEM",id,"SYSTEM_DEACTIVATED",actor(b),s.getName()+" desativado."));}
 @Transactional public AccessProfile saveProfile(Long id,Map<String,Object>b){String name=req(b,"name"),desc=req(b,"description"),sys=req(b,"systemName"),perms=req(b,"permissionsText"),risk=req(b,"riskLevel").toUpperCase(Locale.ROOT);if(!Set.of("BAIXO","MÉDIO","ALTO","CRÍTICO").contains(risk))throw new IllegalArgumentException("Nível de risco inválido.");if(systems.findAllByOrderByNameAsc().stream().noneMatch(s->s.getName().equals(sys)&&s.isActive()))throw new IllegalArgumentException("Selecione um sistema ativo cadastrado.");AccessProfile p=id==null?new AccessProfile(name,desc,sys,perms,risk,bool(b,"active",true)):profiles.findById(id).orElseThrow(()->new NoSuchElementException("Perfil não encontrado."));p.setName(name);p.setDescription(desc);p.setSystemName(sys);p.setPermissionsText(perms);p.setRiskLevel(risk);p.setActive(bool(b,"active",true));p=profiles.save(p);audit.save(new AuditEvent("PROFILE",p.getId(),id==null?"PROFILE_CREATED":"PROFILE_UPDATED",actor(b),name+" em "+sys));return p;}
 @Transactional public void deleteProfile(Long id,Map<String,Object>b){AccessProfile p=profiles.findById(id).orElseThrow(()->new NoSuchElementException("Perfil não encontrado."));p.setActive(false);profiles.save(p);audit.save(new AuditEvent("PROFILE",id,"PROFILE_DEACTIVATED",actor(b),p.getName()+" desativado."));}
 private String req(Map<String,Object>b,String k){Object x=b.get(k);String v=x==null?"":String.valueOf(x).trim();if(v.isBlank())throw new IllegalArgumentException("Campo obrigatório: "+k);return v;} private boolean bool(Map<String,Object>b,String k,boolean def){Object v=b.get(k);return v==null?def:(v instanceof Boolean z?z:Boolean.parseBoolean(String.valueOf(v)));} private String actor(Map<String,Object>b){Object a=b.get("actor");return a==null||String.valueOf(a).isBlank()?"Operador local":String.valueOf(a).trim();}
}
